"""PL-03 step 2: whole-period summary per ticker."""

from statistics import mean, stdev

from risk.types import TickerSummary, VolSeries


def summary_stats(vol: VolSeries, periods_per_year: int = 252) -> tuple[TickerSummary, ...]:
    """Annualized return, volatility, Sharpe and the last rolling volatility (RISK-04).

    Spine version: the daily mean and sample stdev of the returns, not annualized.
    """
    if len(vol.returns.dates) < 2:
        raise ValueError(f"need at least two returns, got {len(vol.returns.dates)}")
    return tuple(_ticker_summary(vol, ticker) for ticker in vol.returns.tickers)


def _ticker_summary(vol: VolSeries, ticker: str) -> TickerSummary:
    series = vol.returns.values[ticker]
    daily_mean = mean(series)
    daily_vol = stdev(series)
    return TickerSummary(
        ticker=ticker,
        ann_return=daily_mean,
        ann_vol=daily_vol,
        sharpe=daily_mean / daily_vol if daily_vol > 0 else 0.0,
        last_vol=vol.values[ticker][-1],
    )
"""PL-03 step 3: maximum drawdown per ticker."""

import math

from risk.types import Drawdown, Returns


def max_drawdown(returns: Returns) -> tuple[Drawdown, ...]:
    """The deepest fall below the running peak, with its peak and trough dates (RISK-05)."""
    dates = (returns.base_date, *returns.dates)
    return tuple(
        _ticker_drawdown(ticker, dates, returns.values[ticker]) for ticker in returns.tickers
    )


def _ticker_drawdown(ticker: str, dates: tuple[str, ...], values: tuple[float, ...]) -> Drawdown:
    """Walk the cumulative log price from `dates[0]`; strict comparisons let the first date win."""
    level = peak = 0.0
    peak_date = dates[0]
    worst = 0.0
    worst_peak = worst_trough = dates[0]
    for date, value in zip(dates[1:], values, strict=True):
        level += value
        if level > peak:
            peak, peak_date = level, date
        elif level - peak < worst:
            worst, worst_peak, worst_trough = level - peak, peak_date, date
    return Drawdown(
        ticker=ticker,
        depth=math.expm1(worst),
        peak_date=worst_peak,
        trough_date=worst_trough,
    )
"""PL-03 step 4: write the JSON report."""

import json
from collections.abc import Mapping, Sequence
from dataclasses import asdict
from pathlib import Path

from risk.types import Drawdown, Report, TickerSummary


def write_report(
    summary: Sequence[TickerSummary], drawdowns: Sequence[Drawdown], out_path: str | Path
) -> Report:
    """`{"tickers": [...]}`, one row per ticker, sorted (REP-01)."""
    by_ticker = {drawdown.ticker: drawdown for drawdown in drawdowns}
    summary_tickers = sorted(item.ticker for item in summary)
    if summary_tickers != sorted(by_ticker) or len(by_ticker) != len(drawdowns):
        raise ValueError(
            f"summary covers {summary_tickers}, drawdowns cover {sorted(d.ticker for d in drawdowns)}"
        )
    rows = tuple(
        _row(item, by_ticker[item.ticker]) for item in sorted(summary, key=lambda s: s.ticker)
    )
    path = Path(out_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps({"tickers": list(rows)}, indent=2) + "\n")
    return Report(path=str(path), rows=rows)


def _row(item: TickerSummary, drawdown: Drawdown) -> Mapping[str, object]:
    return {
        **asdict(item),
        "max_drawdown": drawdown.depth,
        "peak_date": drawdown.peak_date,
        "trough_date": drawdown.trough_date,
    }
